import type { AdrDraft, AdvisorAnswer, ChangeProposal, ImpactReport, Project, RequirementsAnalysis, RiskDraft } from "@/domain/types";

/**
 * Contract every AI backend implements (mock now, Gemini in Stage 3).
 * Implementations MUST return data that already passes the matching Zod schema, and callers
 * treat all results as suggestions: nothing here changes a project by itself.
 */
export interface AIProvider {
  readonly name: "mock" | "gemini";
  /** True when answers are pre-computed rather than generated by a model. Shown in the UI. */
  readonly isMock: boolean;

  /** `context` holds what the project already knows (targets, answers) so it is not asked for again. */
  analyzeRequirements(input: { text: string; context?: string }): Promise<RequirementsAnalysis>;
  /** Clarifying questions for information the project is still missing. */
  suggestQuestions(project: Project): Promise<RequirementsAnalysis["questions"]>;
  generateArchitecture(project: Project): Promise<ChangeProposal>;
  askAdvisor(project: Project, question: string, focusComponentId?: string): Promise<AdvisorAnswer>;
  analyzeImpact(project: Project, componentId: string): Promise<ImpactReport>;
  suggestAdr(project: Project, input: { topic: string; componentId?: string }): Promise<AdrDraft>;
  suggestRisks(project: Project): Promise<RiskDraft[]>;
}
